<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,watch} from 'vue';
import * as echarts from 'echarts/core';
import {LineChart,ScatterChart,HeatmapChart} from 'echarts/charts';
import {GridComponent,TooltipComponent,DataZoomComponent,MarkLineComponent,VisualMapComponent,BrushComponent} from 'echarts/components';
import {CanvasRenderer} from 'echarts/renderers';
import type {PoseFrame,Joint,Marker} from '../types';
import {JOINTS,COLORS} from '../config';
echarts.use([LineChart,ScatterChart,HeatmapChart,GridComponent,TooltipComponent,DataZoomComponent,MarkLineComponent,VisualMapComponent,BrushComponent,CanvasRenderer]);
const props=defineProps<{frames:PoseFrame[];joint:Joint;markers:Marker[];kind?:'angle'|'center'|'heatmap'|'trajectory';expanded?:boolean}>();
const emit=defineEmits<{range:[start:number,end:number]}>();
const element=ref<HTMLElement>();let chart:echarts.ECharts|undefined,observer:ResizeObserver,lastRender=0;
function draw(){if(!chart)return;const frames=props.frames;const grid={left:43,right:20,top:22,bottom:props.kind==='angle'||!props.kind?44:28};const axis={axisLine:{show:false},axisTick:{show:false},axisLabel:{color:'#8b9a98',fontSize:10},splitLine:{lineStyle:{color:'#edf1ef',type:'dashed' as const}}};
  if(props.kind==='heatmap'){const sample=frames.filter((_,i)=>i%Math.max(1,Math.ceil(frames.length/45))===0);chart.setOption({animation:false,grid:{left:48,right:12,top:5,bottom:25},tooltip:{formatter:(p:unknown)=>{const item=p as {value:[number,number,number]};return `${JOINTS[item.value[1]].label} · ${item.value[2].toFixed(1)} °/s`;}},xAxis:{...axis,type:'category',data:sample.map(f=>f.time.toFixed(1)),splitLine:{show:false},axisLabel:{color:'#8b9a98',fontSize:9,interval:Math.max(1,Math.floor(sample.length/4)),formatter:(v:string)=>v+'s'}},yAxis:{...axis,type:'category',data:JOINTS.slice(0,5).map(j=>j.label.slice(0,1)),splitLine:{show:false}},visualMap:{show:false,min:0,max:100,inRange:{color:['#e8f4ed','#bce4cb','#7ac79c','#e3bd76','#e89461']}},series:[{type:'heatmap',data:sample.flatMap((f,x)=>JOINTS.slice(0,5).flatMap((j,y)=>{const v=[f.velocity[j.key].left,f.velocity[j.key].right].filter((v):v is number=>v!==null);return v.length?[[x,y,Math.max(...v.map(Math.abs))]]:[];})),itemStyle:{borderColor:'#fff',borderWidth:3,borderRadius:3}}]},true);return;}
  if(props.kind==='trajectory'){chart.setOption({animation:false,grid,tooltip:{trigger:'axis'},xAxis:{...axis,type:'value',name:'X',min:.3,max:.7},yAxis:{...axis,type:'value',name:'Y',inverse:true,min:.4,max:.7},series:[{type:'line',symbol:'none',data:frames.filter(f=>f.center).map(f=>[f.center!.x,f.center!.y]),lineStyle:{color:'#0f947b',width:2}}]},true);return;}
  const center=props.kind==='center';
  const series=center?[{name:'重心 Y',color:'#18977e',data:frames.map(f=>[f.time,f.center?.y??null])}]:[{name:'左侧',color:COLORS.left,data:frames.map(f=>[f.time,f.angles[props.joint].left])},{name:'右侧',color:COLORS.right,data:frames.map(f=>[f.time,f.angles[props.joint].right])}];
  chart.setOption({animation:false,grid,tooltip:{trigger:'axis',valueFormatter:(v:unknown)=>v===null?'不可用':Number(v).toFixed(center?4:1)+(center?'':'°')},xAxis:{...axis,type:'value',min:frames[0]?.time??0,max:Math.max(frames.at(-1)?.time??1,1),splitLine:{show:false},axisLabel:{...axis.axisLabel,formatter:(v:number)=>v.toFixed(0)+' s'}},yAxis:{...axis,type:'value',min:center?'dataMin':0,max:center?'dataMax':180,axisLabel:{...axis.axisLabel,formatter:(v:number)=>center?v.toFixed(2):v+'°'}},dataZoom:!center?[{type:'inside',filterMode:'none'},{type:'slider',height:12,bottom:0,borderColor:'transparent',backgroundColor:'#f3f7f5',fillerColor:'rgba(24,151,126,.12)',handleStyle:{color:'#78c3ad',borderWidth:0},showDetail:false,brushSelect:true}]:[],series:series.map((s,i)=>({name:s.name,type:'line',data:s.data,symbol:'none',connectNulls:false,sampling:'lttb',lineStyle:{width:2,color:s.color},itemStyle:{color:s.color},areaStyle:center?{color:'rgba(24,151,126,.06)'}:undefined,markLine:i===0?{symbol:'none',label:{fontSize:10,color:'#78938a',formatter:'{b}'},lineStyle:{color:'#9db8ac',type:'dashed'},data:props.markers.map(m=>({name:m.label,xAxis:m.time}))}:undefined}))},{replaceMerge:['series']});
}
onMounted(()=>{chart=echarts.init(element.value);observer=new ResizeObserver(()=>chart?.resize());observer.observe(element.value!);chart.on('datazoom',()=>{const option=chart!.getOption() as {dataZoom?:{start?:number;end?:number}[]};const zoom=option.dataZoom?.[0];if(zoom){const first=props.frames[0]?.time??0,last=props.frames.at(-1)?.time??0;emit('range',first+(last-first)*(zoom.start??0)/100,first+(last-first)*(zoom.end??100)/100);}});draw();});
watch(()=>[props.frames,props.joint,props.markers,props.kind],()=>{const now=performance.now();if(now-lastRender>250){lastRender=now;draw();}});
watch(()=>props.joint,draw);watch(()=>props.markers.length,draw);watch(()=>props.frames.length,length=>{if(length===0)draw();});onBeforeUnmount(()=>{observer?.disconnect();chart?.dispose();});
</script>
<template><div ref="element" class="echart" :class="{'chart-expanded':expanded}" role="img" :aria-label="kind==='center'?'重心起伏时序图':kind==='heatmap'?'关节角速度热力图':'关节角度时序图'"/></template>
